import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    shapes = data[1:]

    face_counts = {
        "Tetrahedron": 4,
        "Cube": 6,
        "Octahedron": 8,
        "Dodecahedron": 12,
        "Icosahedron": 20
    }

    total_faces = 0
    for shape in shapes:
        total_faces += face_counts[shape]

    print(total_faces)

if __name__ == "__main__":
    main()
